@Component("dataRetentionPolicy-subscriber")
public class DataRetentionPolicySubscriber extends BaseSubscriber {

	public DataRetentionPolicySubscriber() {
	}
	
    public SubscriptionQueryResult<List<DataRetentionPolicy>, DataRetentionPolicy> dataRetentionPolicySubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllDataRetentionPolicyQuery(), 
                		ResponseTypes.multipleInstancesOf(DataRetentionPolicy.class),
                		ResponseTypes.instanceOf(DataRetentionPolicy.class));
    }

    public SubscriptionQueryResult<DataRetentionPolicy, DataRetentionPolicy> dataRetentionPolicySubscribe(@DestinationVariable UUID dataRetentionPolicyId) {
        return queryGateway
                .subscriptionQuery(new FindDataRetentionPolicyQuery(new LoadDataRetentionPolicyFilter(dataRetentionPolicyId)), 
                		ResponseTypes.instanceOf(DataRetentionPolicy.class),
                		ResponseTypes.instanceOf(DataRetentionPolicy.class));
    }





}

